// API Route: GET /api/reports/audit
// Serves audit reports generated by auditReport.ts (migrated from RPTAUD00.cbl)

import { NextResponse } from "next/server";
import { withErrorHandler, AppError } from "@/lib/errorHandler";
import { generateAuditReport } from "@/services/reporting/auditReport";
import type { AuditAction, AuditReportFilters, ApiResponse, AuditReportOutput } from "@/types";

const VALID_ACTIONS: AuditAction[] = [
  "CREATE", "UPDATE", "DELETE", "INQUIRE",
  "LOGIN", "LOGOUT", "STARTUP", "SHUTDOWN",
];

export const GET = withErrorHandler(async (request: Request) => {
  const start = Date.now();
  const { searchParams } = new URL(request.url);

  const startDateParam = searchParams.get("startDate");
  const endDateParam = searchParams.get("endDate");
  const userId = searchParams.get("userId");
  const portfolioId = searchParams.get("portfolioId");
  const action = searchParams.get("action");

  const filters: AuditReportFilters = {};

  if (startDateParam) {
    const d = new Date(startDateParam);
    if (isNaN(d.getTime())) {
      throw new AppError({
        message: "Invalid startDate parameter.",
        httpStatus: 400,
        severity: 1,
        errorCode: "BADDATE",
      });
    }
    filters.startDate = d;
  }

  if (endDateParam) {
    const d = new Date(endDateParam);
    if (isNaN(d.getTime())) {
      throw new AppError({
        message: "Invalid endDate parameter.",
        httpStatus: 400,
        severity: 1,
        errorCode: "BADDATE",
      });
    }
    filters.endDate = d;
  }

  if (userId) {
    filters.userId = userId;
  }

  if (portfolioId) {
    filters.portfolioId = portfolioId;
  }

  if (action) {
    if (!VALID_ACTIONS.includes(action as AuditAction)) {
      throw new AppError({
        message: `Invalid action parameter. Valid values: ${VALID_ACTIONS.join(", ")}`,
        httpStatus: 400,
        severity: 1,
        errorCode: "BADACT",
      });
    }
    filters.action = action as AuditAction;
  }

  const report = await generateAuditReport(filters);

  const response: ApiResponse<AuditReportOutput> = {
    success: true,
    data: report,
    metadata: {
      generatedAt: new Date().toISOString(),
      processingTimeMs: Date.now() - start,
    },
  };

  return NextResponse.json(response);
});
